solution:
type Ingredient = {
  name: Str;
  amount: Float64;
  unit: Str;
}

type Recipe = {
  title: Str;
  servings: Int;
  main_ingredient: Ingredient;
}

fn scale_recipe(recipe: Recipe, factor: Float64) -> Recipe {
  let scaled = Ingredient{
    name: recipe.main_ingredient.name;
    amount: recipe.main_ingredient.amount * factor;
    unit: recipe.main_ingredient.unit;
  };
  return Recipe{
    title: recipe.title;
    servings: recipe.servings;
    main_ingredient: scaled;
  };
}

fn main() -> Int {
  let butter = Ingredient{ name: "Butter"; amount: 0.5; unit: "cups"; };
  let cookies = Recipe{ title: "Cookies"; servings: 12; main_ingredient: butter; };
  let doubled = scale_recipe(cookies, 2.0);
  return doubled.main_ingredient.amount as Int;
}
